/**
 * MODULE-WISE CRITICAL PATH CALCULATION ENGINE
 * Logic: Total Float <= 0 AND Percent Complete < 100%
 * Dependencies: FS, SS, FF, SF and Lags
 * IMPORTANT:
 * - Uses parentId for module grouping
 * - Only returns rows where Critical status CHANGES (true ↔ false)
 * - Includes Task id (Tidxxxx) in output for easy identification
 */
const items = $input.all();
const rowByNumber = {};
const rowById = {};
const successors = {};
const outDegree = {};

// ─── HELPERS ─────────────────────────────────────────────────────────────
const parseDurationToDays = (str) => parseFloat(String(str || '').replace(/[^\d.-]/g, '')) || 0;
const parseLagToDays = (lagStr) => {
    if (!lagStr) return 0;
    const cleaned = lagStr.replace(/\s/g, '');
    const sign = cleaned.startsWith('-') ? -1 : 1;
    return sign * (parseFloat(cleaned.replace(/[+-]/g, '')) || 0);
};
const dateToMs = (date) => (date instanceof Date && !isNaN(date)) ? date.getTime() : 0;
const isWorkingDay = (date) => date.getDay() !== 0 && date.getDay() !== 6;
const subtractWorkingDays = (endDate, days) => {
    if (!endDate || days <= 0) return endDate || new Date(0);
    let current = new Date(endDate);
    let remaining = days;
    while (remaining > 0) {
        current.setDate(current.getDate() - 1);
        if (isWorkingDay(current)) remaining -= 1;
    }
    return current;
};

// ─── STEP 1: BUILD TASK DATA ─────────────────────────────────────────────
items.forEach(item => {
    const data = item.json;
    const rowId = String(data._metadata?.rowId || data.id);
    const rowNumber = data._metadata?.rowNumber || (items.indexOf(item) + 1);
    if (!rowId || !rowNumber) return;

    const currentCritical = data["Critical"] === true ||
                           String(data["Critical"] || '').toLowerCase() === 'true';

    rowById[rowId] = {
        id: rowId,
        rowNumber,
        taskId: data["Task id"] || "N/A",  // ← Added Task id (Tidxxxx)
        name: data["Task Name"] || "Unnamed",
        durationDays: parseDurationToDays(data.Duration),
        percentComplete: parseFloat(String(data["Percentage Complete"] || "0").replace('%', '')) || 0,
        efDate: data.Finish ? new Date(data.Finish) : null,
        preds: data.Predecessors ? String(data.Predecessors).split(/,\s*/) : [],
        lsDate: null,
        lfDate: null,
        currentCritical,
        parentId: data._metadata?.parentId ? String(data._metadata.parentId) : null
    };
    rowByNumber[rowNumber] = rowById[rowId];
    successors[rowId] = [];
    outDegree[rowId] = 0;
});

// ─── STEP 2: BUILD SUCCESSORS ────────────────────────────────────────────
Object.values(rowById).forEach(task => {
    task.preds.forEach(p => {
        const match = p.trim().match(/^(\d+)\s*([FS|SS|FF|SF]{2})?\s*([+-]\s*\d*\.?\d*\s*[dwhm]?)?.*$/i);
        if (!match) return;
        const predNum = parseInt(match[1], 10);
        const predTask = rowByNumber[predNum];
        if (!predTask) return;
        successors[predTask.id].push({
            to: task.id,
            type: (match[2] || 'FS').toUpperCase(),
            lagDays: parseLagToDays(match[3] || '0d')
        });
        outDegree[predTask.id]++;
    });
});

// ─── STEP 3: GROUP BY MODULE (using parentId) ────────────────────────────
const modules = {};
const visited = new Set();

function collectModule(rootTask) {
    const moduleTasks = [rootTask];
    visited.add(rootTask.id);
    let q = [rootTask];
    while (q.length > 0) {
        const current = q.shift();
        Object.values(rowById).forEach(task => {
            if (task.parentId === current.id && !visited.has(task.id)) {
                moduleTasks.push(task);
                visited.add(task.id);
                q.push(task);
            }
        });
    }
    return moduleTasks;
}

// Find root tasks (no parent or parent not in sheet)
Object.values(rowById).forEach(task => {
    if (!visited.has(task.id) && (!task.parentId || !rowById[task.parentId])) {
        modules[task.id] = collectModule(task);
    }
});

// Fallback: if no hierarchy detected, treat as one big module
if (Object.keys(modules).length === 0) {
    modules["global"] = Object.values(rowById);
}

// ─── STEP 4: CALCULATE PER MODULE ────────────────────────────────────────
const batchUpdates = [];

Object.keys(modules).forEach(moduleKey => {
    const moduleTasks = modules[moduleKey];

    // Module-specific end date
    const moduleFinishMs = Math.max(...moduleTasks.map(t => dateToMs(t.efDate || new Date(0))));
    const moduleFinishDate = new Date(moduleFinishMs);

    // Reset LF for module
    moduleTasks.forEach(t => t.lfDate = new Date(moduleFinishDate));

    // Backward pass within module
    let queue = moduleTasks.filter(t => outDegree[t.id] === 0).map(t => t.id);
    while (queue.length > 0) {
        const currentId = queue.shift();
        const task = rowById[currentId];
        task.lsDate = subtractWorkingDays(task.lfDate, task.durationDays);

        task.preds.forEach(p => {
            const match = p.trim().match(/^(\d+)\s*([FS|SS|FF|SF]{2})?\s*([+-]\s*\d*\.?\d*\s*[dwhm]?)?.*$/i);
            if (!match) return;
            const predNum = parseInt(match[1], 10);
            const predTask = rowByNumber[predNum];
            if (!predTask || !moduleTasks.find(t => t.id === predTask.id)) return;

            const type = (match[2] || 'FS').toUpperCase();
            const lag = parseLagToDays(match[3] || '0d');

            let latestLF = new Date(task.lsDate);
            if (type === 'FS') latestLF = subtractWorkingDays(task.lsDate, lag);
            else if (type === 'SS') latestLF = addWorkingDays(subtractWorkingDays(task.lsDate, lag), predTask.durationDays);
            else if (type === 'FF') latestLF = subtractWorkingDays(task.lfDate, lag);
            else if (type === 'SF') latestLF = addWorkingDays(subtractWorkingDays(task.lfDate, lag), predTask.durationDays);

            if (dateToMs(predTask.lfDate) > dateToMs(latestLF)) {
                predTask.lfDate = new Date(latestLF);
            }

            outDegree[predTask.id]--;
            if (outDegree[predTask.id] === 0) queue.push(predTask.id);
        });
    }

    // Generate updates for changed tasks
    moduleTasks.forEach(task => {
        const tfDays = task.efDate && task.lfDate
            ? Math.round((dateToMs(task.lfDate) - dateToMs(task.efDate)) / 86400000)
            : null;

        const isCritical = tfDays !== null && tfDays <= 0 && task.percentComplete < 100;

        if (task.currentCritical !== isCritical) {
            batchUpdates.push({
                rowId: task.id,
                taskId: task.taskId || "N/A",  // ← Added Task id (Tidxxxx)
                updates: { "Critical": isCritical },
                change: task.currentCritical ? "true → false" : "false → true",
                DISPLAY_TaskName: task.name,
                DISPLAY_TotalFloat: tfDays !== null ? tfDays + "d" : "N/A",
                DISPLAY_PercentComplete: task.percentComplete + "%"
            });
        }
    });
});

// ─── FINAL OUTPUT ────────────────────────────────────────────────────────
return [{
    json: {
        batchUpdates,                    // only changed rows (with rowId & Critical)
        shouldUpdate: batchUpdates.length > 0,
        changedCount: batchUpdates.length,
        timestamp: new Date().toISOString()
    }
}];
